+      :root {
+        color-scheme: light;
+        --bg: #f4f7fb;
+        --card: rgba(255, 255, 255, 0.88);
+        --card-border: rgba(148, 163, 184, 0.22);
+        --text: #0f172a;
+        --muted: #475569;
+        --accent: #7c3aed;
+        --accent-soft: #ede9fe;
+        --shadow: 0 20px 50px rgba(15, 23, 42, 0.08);
