+        color: var(--text);
+        background:
+          radial-gradient(circle at top, #ffffff 0%, transparent 42%),
+          linear-gradient(180deg, #eef2ff 0%, var(--bg) 100%);
+        min-height: 100vh;
+      }
+
+      .page {
+        width: min(960px, calc(100% - 32px));
+        margin: 0 auto;
+        padding: 56px 0 72px;
+      }
+
+      .hero {
+        padding: 28px 28px 12px;
+        margin-bottom: 24px;
+      }
+
+      .eyebrow {
+        display: inline-flex;
+        align-items: center;
+        gap: 8px;
+        padding: 8px 14px;
+        border-radius: 999px;
+        background: var(--accent-soft);
+        color: #5b21b6;
+        font-size: 0.875rem;
+        font-weight: 700;
+        letter-spacing: 0.02em;
+      }
+
+      h1 {
+        margin: 18px 0 10px;
+        font-size: clamp(2.2rem, 4vw, 4rem);
+        line-height: 1.02;
+        letter-spacing: -0.04em;
+      }
+
+      .lead {
+        max-width: 60ch;
+        margin: 0;
+        color: var(--muted);
+        font-size: 1.05rem;
+        line-height: 1.7;
+      }
+
+      .faq {
+        display: grid;
+        gap: 16px;
+      }
+
+      .example {
+        border: 1px solid var(--card-border);
+        border-radius: var(--radius);
+        background: var(--card);
+        box-shadow: var(--shadow);
+        overflow: clip;
+        backdrop-filter: blur(18px);
+      }
+
+      .question {
+        display: flex;
+        width: 100%;
+        align-items: center;
+        justify-content: space-between;
+        gap: 16px;
+        padding: 22px 24px;
+        border: 0;
+        background: transparent;
+        color: inherit;
+        font: inherit;
+        text-align: left;
+        cursor: pointer;
+      }
+
+      .question:hover {
+        background: rgba(124, 58, 237, 0.05);
+      }
+
+      .question:focus-visible {
+        outline: 3px solid rgba(124, 58, 237, 0.35);
+        outline-offset: -3px;
+      }
+
+      .question h2 {
+        margin: 0;
+        font-size: 1.06rem;
+        line-height: 1.4;
+      }
+
+      .chevron {
+        flex: 0 0 auto;
+        width: 36px;
+        height: 36px;
+        border-radius: 999px;
+        display: grid;
+        place-items: center;
+        background: #f8fafc;
+        color: #4c1d95;
+        transition: transform 180ms ease, background 180ms ease;
+      }
+
+      .question[aria-expanded="true"] .chevron {
+        transform: rotate(180deg);
+        background: var(--accent-soft);
+      }
+
+      .details {
+        display: grid;
+        grid-template-rows: 0fr;
+        transition: grid-template-rows 220ms ease;
+      }
+
+      .details.open {
+        grid-template-rows: 1fr;
+      }
+
+      .details-inner {
+        overflow: hidden;
+      }
+
+      .answer {
+        padding: 0 24px 24px;
+        color: var(--muted);
+        line-height: 1.7;
+      }
+
+      .answer p {
+        margin: 0;
+      }
+
+      @media (max-width: 640px) {
+        .page {
+          width: min(100% - 20px, 960px);
+          padding-top: 22px;
+        }
+
+        .hero {
+          padding: 20px 8px 8px;
+        }
+
+        .question,
+        .answer {
+          padding-left: 18px;
+          padding-right: 18px;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <main class="page">
+      <section class="hero">
+        <div class="eyebrow">Cat FAQ</div>
+        <h1>Everything you wanted to know about cats</h1>
+        <p class="lead">
+          A clean, modern FAQ with accordion-style answers that start collapsed and expand on
+          demand.
+        </p>
+      </section>
+
+      <section id="faq" class="faq" aria-label="Frequently asked questions about cats"></section>
+    </main>
+
+    <script>
+      const faqData = [
+        {
+          question: "Why do cats purr?",
+          answer:
+            "Cats purr for many reasons: they may be relaxed, asking for attention, or self-soothing when they are stressed or healing.",
+        },
+        {
+          question: "Do cats need baths?",
+          answer:
+            "Usually not. Most cats groom themselves well, but an occasional bath can help if they get into something sticky or messy.",
+        },
+        {
+          question: "Why do cats knead blankets?",
+          answer:
+            "Kneading is a comforting behavior often linked to kittenhood. Adult cats do it when they feel safe, cozy, or content.",
+        },
+        {
+          question: "How much sleep do cats need?",
+          answer:
+            "Cats can sleep 12 to 16 hours a day, and some even more. It is a normal part of being a predator that conserves energy for bursts of activity.",
+        },
+        {
+          question: "What makes cats such good companions?",
+          answer:
+            "Cats blend independence with affection. They are playful, observant, and often bring a calm, low-maintenance presence to a home.",
+        },
+      ];
+
+      function FAQItem({ question, answer, index }) {
+        const isOpen = false;
+        return `
+          <div class="example" data-faq-item>
+            <button class="question" type="button" aria-expanded="${isOpen}" aria-controls="faq-panel-${index}" id="faq-trigger-${index}">
+              <h2>${question}</h2>
+              <span class="chevron" aria-hidden="true">⌄</span>
+            </button>
+            <div class="details" id="faq-panel-${index}" role="region" aria-labelledby="faq-trigger-${index}">
+              <div class="details-inner">
+                <div class="answer">
+                  <p>${answer}</p>
+                </div>
+              </div>
+            </div>
+          </div>
+        `;
+      }
+
+      function FAQApp(items) {
+        return items.map((item, index) => FAQItem({ ...item, index })).join("");
+      }
+
+      const faqRoot = document.getElementById("faq");
+      faqRoot.innerHTML = FAQApp(faqData);
+
+      faqRoot.addEventListener("click", (event) => {
+        const button = event.target.closest(".question");
+        if (!button) return;
+
+        const example = button.closest(".example");
+        const panel = example.querySelector(".details");
+        const expanded = button.getAttribute("aria-expanded") === "true";
+
+        button.setAttribute("aria-expanded", String(!expanded));
+        panel.classList.toggle("open", !expanded);
+      });
+    </script>
+  </body>
+</html>
*** End Patch
