          A clean, modern FAQ with accordion-style answers that start collapsed and expand on
          demand.
        </p>
      </section>

      <section id="faq" class="faq" aria-label="Frequently asked questions about cats"></section>
    </main>

    <script>
      const faqData = [
        {
          question: "Why do cats purr?",
          answer:
            "Cats purr for many reasons: they may be relaxed, asking for attention, or self-soothing when they are stressed or healing.",
        },
        {
          question: "Do cats need baths?",
          answer:
            "Usually not. Most cats groom themselves well, but an occasional bath can help if they get into something sticky or messy.",
        },
        {
          question: "Why do cats knead blankets?",
          answer:
            "Kneading is a comforting behavior often linked to kittenhood. Adult cats do it when they feel safe, cozy, or content.",
        },
        {
          question: "How much sleep do cats need?",
          answer:
            "Cats can sleep 12 to 16 hours a day, and some even more. It is a normal part of being a predator that conserves energy for bursts of activity.",
        },
        {
          question: "What makes cats such good companions?",
          answer:
            "Cats blend independence with affection. They are playful, observant, and often bring a calm, low-maintenance presence to a home.",
        },
      ];

      function FAQItem({ question, answer, index }) {
        const isOpen = false;
        return `
          <div class="example" data-faq-item>
            <button class="question" type="button" aria-expanded="${isOpen}" aria-controls="faq-panel-${index}" id="faq-trigger-${index}">
              <h2>${question}</h2>
              <span class="chevron" aria-hidden="true">⌄</span>
            </button>
            <div class="details" id="faq-panel-${index}" role="region" aria-labelledby="faq-trigger-${index}">
              <div class="details-inner">
                <div class="answer">
                  <p>${answer}</p>
                </div>
              </div>
            </div>
          </div>
        `;
      }

      function FAQApp(items) {
        return items.map((item, index) => FAQItem({ ...item, index })).join("");
      }

