                   <p>${answer}</p>
                 </div>
               </div>
             </div>
           </div>
         `;
       }

       function FAQApp(items) {
         return items.map((item, index) => FAQItem({ ...item, index })).join("");
       }

       const faqRoot = document.getElementById("faq");
       faqRoot.innerHTML = FAQApp(faqData);

       faqRoot.addEventListener("click", (event) => {
         const button = event.target.closest(".question");
         if (!button) return;

         const example = button.closest(".example");
         const panel = example.querySelector(".details");
         const expanded = button.getAttribute("aria-expanded") === "true";

         button.setAttribute("aria-expanded", String(!expanded));
         panel.classList.toggle("open", !expanded);
       });
     </script>
   </body>
 </html>

